export const translateGenre = (genre) => {
  const map = {
    'Action': 'Боевик', 'Adventure': 'Приключения', 'Comedy': 'Комедия', 'Drama': 'Драма',
    'Fantasy': 'Фэнтези', 'Horror': 'Ужасы', 'Mystery': 'Детектив', 'Romance': 'Романтика',
    'Sci-Fi': 'Фантастика', 'Slice of Life': 'Повседневность', 'Sports': 'Спорт',
    'Supernatural': 'Сверхъестественное', 'Thriller': 'Триллер', 'Mecha': 'Меха',
    'Music': 'Музыка', 'Psychological': 'Психологическое', 'Ecchi': 'Этти', 'Josei': 'Дзёсэй',
    'Seinen': 'Сэйнэн', 'Shoujo': 'Сёдзё', 'Shounen': 'Сёнэн'
  };
  return map[genre] || genre;
};

export const translateFormat = (format) => {
  const map = { 
    'TV': 'ТВ', 
    'TV_SHORT': 'ТВ-короткий', 
    'OVA': 'OVA', 
    'ONA': 'ONA', 
    'MOVIE': 'Фильм', 
    'SPECIAL': 'Спешл', 
    'MUSIC': 'Клип' 
  };
  return map[format] || format;
};

export const translateStatus = (status) => {
  const map = { 
    'RELEASING': 'Онгоинг', 
    'FINISHED': 'Завершено', 
    'NOT_YET_RELEASED': 'Анонс', 
    'CANCELLED': 'Отменено' 
  };
  return map[status] || status;
};

// --- ЖЕСТКИЙ СБРОС КЭША (v23_clean) ---
const CACHE_VERSION = 'v59_no_duplicates';
if (localStorage.getItem('anibox_cache_version') !== CACHE_VERSION) {
  localStorage.removeItem('anibox_title_cache');
  localStorage.setItem('anibox_cache_version', CACHE_VERSION);
}

const cleanString = (str) => {
  if (!str) return '';
  return str.toLowerCase()
    .replace(/[^\w\s\u0400-\u04FF]/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
};

